CREATE TABLE push_keys(id INTEGER PRIMARY KEY CHECK(id=1),public_key TEXT NOT NULL,private_key TEXT NOT NULL);
CREATE TABLE push_subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,endpoint TEXT NOT NULL UNIQUE,subscription TEXT NOT NULL,created_at INTEGER NOT NULL,last_success_at INTEGER,last_error TEXT);
CREATE INDEX push_subscriptions_user ON push_subscriptions(user_id);
CREATE TABLE push_outbox(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,category TEXT NOT NULL,payload TEXT NOT NULL,created_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,last_attempt_at INTEGER,finished_at INTEGER,last_error TEXT);
CREATE INDEX push_outbox_pending ON push_outbox(finished_at,created_at);
CREATE TABLE push_receipts(event_id TEXT NOT NULL REFERENCES push_outbox(id) ON DELETE CASCADE,subscription_id TEXT NOT NULL,PRIMARY KEY(event_id,subscription_id));
CREATE TRIGGER friend_push_insert AFTER INSERT ON friend_notifications BEGIN
 INSERT INTO push_outbox(id,user_id,category,payload,created_at) VALUES(lower(hex(randomblob(16))),NEW.user_id,CASE WHEN NEW.kind='request' THEN 'friendRequests' ELSE 'friendAccepted' END,json_object('title',COALESCE((SELECT json_extract(profile,'$.name') FROM users WHERE id=NEW.actor_id),(SELECT friend_username FROM users WHERE id=NEW.actor_id))||CASE WHEN NEW.kind='request' THEN ' sent you a friend request' ELSE ' accepted your friend request' END,'body','Fancy Knowing','url','/?inbox=1'),NEW.created_at);
END;
CREATE TRIGGER friend_push_update AFTER UPDATE OF created_at ON friend_notifications WHEN NEW.created_at<>OLD.created_at BEGIN
 INSERT INTO push_outbox(id,user_id,category,payload,created_at) VALUES(lower(hex(randomblob(16))),NEW.user_id,CASE WHEN NEW.kind='request' THEN 'friendRequests' ELSE 'friendAccepted' END,json_object('title',COALESCE((SELECT json_extract(profile,'$.name') FROM users WHERE id=NEW.actor_id),(SELECT friend_username FROM users WHERE id=NEW.actor_id))||CASE WHEN NEW.kind='request' THEN ' sent you a friend request' ELSE ' accepted your friend request' END,'body','Fancy Knowing','url','/?inbox=1'),NEW.created_at);
END;
CREATE TRIGGER challenge_push_insert AFTER INSERT ON challenge_notifications WHEN NEW.kind IN ('invite','score') OR (SELECT group_mode FROM trivia_games WHERE id=NEW.game_id)=0 BEGIN
 INSERT INTO push_outbox(id,user_id,category,payload,created_at) VALUES(lower(hex(randomblob(16))),NEW.user_id,CASE WHEN NEW.kind='invite' THEN 'challengeInvites' ELSE 'quizResults' END,json_object('title',CASE WHEN NEW.kind='invite' THEN COALESCE((SELECT json_extract(u.profile,'$.name') FROM users u JOIN trivia_games g ON u.id=g.creator_id WHERE g.id=NEW.game_id),'A friend')||' challenged you' ELSE COALESCE(NEW.message,'Your challenge result is ready') END,'body',(SELECT topic FROM trivia_games WHERE id=NEW.game_id),'url','/?game='||NEW.game_id),NEW.created_at);
END;
CREATE TRIGGER challenge_push_update AFTER UPDATE OF created_at,kind,message ON challenge_notifications WHEN (NEW.created_at<>OLD.created_at OR NEW.kind<>OLD.kind OR NEW.message IS NOT OLD.message) AND (NEW.kind IN ('invite','score') OR (SELECT group_mode FROM trivia_games WHERE id=NEW.game_id)=0) BEGIN
 INSERT INTO push_outbox(id,user_id,category,payload,created_at) VALUES(lower(hex(randomblob(16))),NEW.user_id,CASE WHEN NEW.kind='invite' THEN 'challengeInvites' ELSE 'quizResults' END,json_object('title',CASE WHEN NEW.kind='invite' THEN COALESCE((SELECT json_extract(u.profile,'$.name') FROM users u JOIN trivia_games g ON u.id=g.creator_id WHERE g.id=NEW.game_id),'A friend')||' challenged you' ELSE COALESCE(NEW.message,'Your challenge result is ready') END,'body',(SELECT topic FROM trivia_games WHERE id=NEW.game_id),'url','/?game='||NEW.game_id),NEW.created_at);
END;
